import pandas as pd


def _get_input(inputs: dict, name: str) -> pd.DataFrame:
    """Fetch an input dataframe tolerating case differences in the key name."""
    if name in inputs:
        return inputs[name]
    lname = name.lower()
    for k in inputs:
        if k.lower() == lname:
            return inputs[k]
    raise KeyError(name)


def run(inputs: dict) -> dict:
    dim = _get_input(inputs, 'DIM_ACCOUNT').copy()
    stg = _get_input(inputs, 'STG_ACCOUNT').copy()

    # Normalise date columns to pandas Timestamps (NaT for missing)
    dim['eff_start_date'] = pd.to_datetime(dim['eff_start_date'])
    dim['eff_end_date'] = pd.to_datetime(dim['eff_end_date'])
    stg['update_date'] = pd.to_datetime(stg['update_date'])

    # Build in-memory state: account_id -> list of version dicts
    state = {}
    for _, row in dim.iterrows():
        aid = row['account_id']
        state.setdefault(aid, []).append({
            'plan': row['plan'],
            'eff_start_date': row['eff_start_date'],
            'eff_end_date': row['eff_end_date'],
            'is_current': row['is_current'],
        })

    # Order staged rows exactly as the cursor would: account_id, update_date ASC
    # (stable sort preserves original relative order for any remaining ties)
    stg_sorted = stg.sort_values(['account_id', 'update_date'], kind='mergesort')

    def plans_equal(a, b):
        a_na = pd.isna(a)
        b_na = pd.isna(b)
        if a_na and b_na:
            return True
        if a_na != b_na:
            return False
        return a == b

    for _, s in stg_sorted.iterrows():
        aid = s['account_id']
        plan = s['plan']
        upd = s['update_date']

        versions = state.setdefault(aid, [])

        if not versions:
            # No existing version at all for this account
            versions.append({
                'plan': plan,
                'eff_start_date': upd,
                'eff_end_date': pd.NaT,
                'is_current': 1,
            })
            continue

        # Find the version that covers update_date:
        # eff_start_date <= upd < eff_end_date (NULL end == open/infinite)
        v = None
        for ver in versions:
            start = ver['eff_start_date']
            end = ver['eff_end_date']
            if start <= upd and (pd.isna(end) or upd < end):
                v = ver
                break

        if v is None:
            # update_date is earlier than the account's first version
            f = min(versions, key=lambda x: x['eff_start_date'])
            versions.append({
                'plan': plan,
                'eff_start_date': upd,
                'eff_end_date': f['eff_start_date'],
                'is_current': 0,
            })
        else:
            if plans_equal(v['plan'], plan):
                # no-op
                pass
            elif upd == v['eff_start_date']:
                # same-day correction, no new version created
                v['plan'] = plan
            else:
                # split v at upd
                versions.append({
                    'plan': plan,
                    'eff_start_date': upd,
                    'eff_end_date': v['eff_end_date'],
                    'is_current': v['is_current'],
                })
                v['eff_end_date'] = upd
                v['is_current'] = 0

    # Materialise output rows
    rows = []
    for aid, versions in state.items():
        for ver in versions:
            rows.append({
                'account_id': aid,
                'plan': ver['plan'],
                'eff_start_date': ver['eff_start_date'],
                'eff_end_date': ver['eff_end_date'],
                'is_current': ver['is_current'],
            })

    out = pd.DataFrame(
        rows,
        columns=['account_id', 'plan', 'eff_start_date', 'eff_end_date', 'is_current'],
    )

    if not out.empty:
        out['account_id'] = out['account_id'].astype(dim['account_id'].dtype if not dim.empty else out['account_id'].dtype)
        out['is_current'] = out['is_current'].astype('int64')
        out = out.sort_values(['account_id', 'eff_start_date'], kind='mergesort').reset_index(drop=True)

    return {'dim_account_out': out}
